// 改めた結果 (reframe)。生成サマリの描画に使う。
type recordRecurrence struct {
	Status         string                     `yaml:"status"`
	Evidence       []recordRecurrenceEvidence `yaml:"evidence"`
	DeclinedReason string                     `yaml:"declined_reason"`
	Reframe        *recordReframe             `yaml:"reframe"`
}

// recordRecurrenceEvidence は旧様式の検知の根拠 1 件。condition は fix-derived
// (修正由来の指摘が続いた) / same-location (同じ場所への採択が続いた)。
// finding_id は同じ回の採択の id、prior_run は比べた回の 1 始まりの番号、
// prior は比べた先。生成サマリの描画に使う。
type recordRecurrenceEvidence struct {
	Condition string `yaml:"condition"`
	FindingID int    `yaml:"finding_id"`
	PriorRun  int    `yaml:"prior_run"`
	Prior     string `yaml:"prior"`
	Reason    string `yaml:"reason"`
}

// recordReframe は旧様式の reframe (検知の後に問題の捉え方を改めた結果)。
// source は human (人間の確認から出た) / skill (スキルの見解から出た)。
// 生成サマリの描画に使う。
type recordReframe struct {
	Pattern   string `yaml:"pattern"`
	Axes      string `yaml:"axes"`
	RootCause string `yaml:"root_cause"`
	FixUnit   string `yaml:"fix_unit"`
	Source    string `yaml:"source"`
}

type recordFinding struct {
	ID              int               `yaml:"id"`
	File            string            `yaml:"file"`
	Line            int               `yaml:"line"`
	Summary         string            `yaml:"summary"`
	Category        string            `yaml:"category"`
	Audience        string            `yaml:"audience"`
	AudienceInitial string            `yaml:"audience_initial"`
	Consequence     recordConsequence `yaml:"consequence"`
	PremiseCheck    recordPremise     `yaml:"premise_check"`
	GatesFired      []string          `yaml:"gates_fired"`
	Verdict         string            `yaml:"verdict"`
	VerdictReason   string            `yaml:"verdict_reason"`
	PlanRef         *recordPlanRef    `yaml:"plan_ref"`
	Origin          string            `yaml:"origin"`
	// PriorDefect は D8 (このブランチより前からある欠陥か) の結果。D8 で判定した指摘
	// (premise_check.result が verified) にだけ書く。verdict_reason の自由記述に書く
	// 規則だけでは、書き忘れても検査が何も報告しなかったため、キーにした (#110)。
	PriorDefect *recordPriorDefect `yaml:"prior_defect"`
	Attrs       map[string]any     `yaml:"attrs"`
}

// recordPriorDefect は findings[].prior_defect を表し、D8 の条件 (1)(2) の結果を持つ。
// line_check は (1) (対象の行が全量の起点から変わっていない) の結果で、同梱の道具
// lineorigin の結果をそのまま書く。same_defect は (2) (全量の起点の内容でも同じ欠陥が
// 成り立つ) の結果で、(1) が holds のときだけ書く。D8 が当たったかどうかは書かず、
// (1)(2) から導く (priorDefectHit)。導ける値を重ねて書くと、両者が矛盾する記録を書けてしまうため。
type recordPriorDefect struct {
	Base             string `yaml:"base"`
	LineCheck        string `yaml:"line_check"`
	LineReason       string `yaml:"line_reason"`
	SameDefect       string `yaml:"same_defect"`
	SameDefectReason string `yaml:"same_defect_reason"`
}

// priorDefectHit は D8 が当たったかを (1)(2) の結果から導く。(1) が成り立ち、(2) が
// 成り立つか確認できないときに当たる (judgment-flow.md の D8 の行)。
func priorDefectHit(pd *recordPriorDefect) bool {
	return pd.LineCheck == "holds" && (pd.SameDefect == "holds" || pd.SameDefect == "unverifiable")
}

// recordPriorDefectFirstRun は、記録の中で最初に prior_defect を書いた回の添字を返す。
// 無ければ -1。この回と、それより後の回では prior_defect を必須にする。それより前の回と、
// 1 度も書いていない記録は、D8 の無い判定フローか、D8 の結果を verdict_reason に書く
// 規則で判定したものと見なす。ディレクトリに残る過去の記録と、利用者が版を上げる前に書いた
// 回を、書き換えさせずに通すため。回の date で区切らないのは、日付が、どの規則で判定
// したかを表さないため (同じ日に両方の規則の回がありうる。版を上げる日は利用者ごとに違う)。
func recordPriorDefectFirstRun(runs []recordRun) int {
	for ri, run := range runs {
		for _, fd := range run.Findings {
			if fd.PriorDefect != nil {
				return ri
			}
		}
	}
	return -1
}

type recordConsequence struct {
	Condition     string `yaml:"condition"`
	Who           string `yaml:"who"`
	What          string `yaml:"what"`
	Detectability string `yaml:"detectability"`
}

type recordPremise struct {
	Stages string `yaml:"stages"`
	Result string `yaml:"result"`
}

// recordPlanRef は採択の束ね先 (どの回のどの問題で直すか) の構造化参照。
// 回をまたいで同因の指摘を束ねたとき (並列レビューの運用)、対応関係を
// 自由記述でなく機械で辿れる形で残す。run は同じファイル内の 1 始まりの回番号。
type recordPlanRef struct {
	Run     int    `yaml:"run"`
	Problem string `yaml:"problem"`
}

type recordPlan struct {
	ProblemID  string `yaml:"problem_id"`
	Cause      string `yaml:"cause"`
	FindingIDs []int  `yaml:"finding_ids"`
	// Approach (修正方法) と Order (順序) は review-triage-fix の立案フェーズが書く。
	// 書く条件は status ごとに決まる。pending / done / done-external では approach が
	// 必須、awaiting-human では任意 (人間の回答の後に書く)、investigated (調査フェーズの
	// 結果だけを持つ) では両方とも書かない。検査は recordSemanticProblems。
	Approach string `yaml:"approach"`
	// Investigation は修正方法を決める前の調査 (類似箇所・影響範囲) の範囲と結果。
	// 無いことは「未調査」を意味し、「調査済みで波及なし」は scope だけを書いた
	// 値で表す。この 2 つを記録上で区別するため、ポインタで有無を持つ。
	// status: investigated (調査済み) では必須で、無ければ検査が報告する。
	// 調査の手順の SSOT は review-triage-fix の references/investigation.md。
	Investigation *recordInvestigation `yaml:"investigation"`
	// Verification は修正の後の検証のうち、観点 B (周りの記述を再確認する) で読んだ範囲。任意だが、
	// 書くなら near_edges が要る (無いと「書いたつもりの検証」が無い扱いになる)。
	// 範囲は同梱の道具 nearedges の出力から写す (record-schema.md「検証」)。
	Verification *recordVerification `yaml:"verification"`
	// DocDag は修正の後の doc-dag の確認 (対象と、どちらが SSOT か決まっていない重複・参照の循環の有無と対処)。任意だが、
	// 書くなら scope と result が要る (record-schema.md「doc-dag の確認」)。
	DocDag    *recordDocDag `yaml:"doc_dag"`
	Options   string        `yaml:"options"`
	Order     int           `yaml:"order"`
	DependsOn []string      `yaml:"depends_on"`
	SHA       string        `yaml:"sha"`
	Status    string        `yaml:"status"`
	// AppliedExternalURL / Notes は status: done-external の反映先の記録。
	// リポジトリ外の成果物 (PR 本文・Issue のコメント・外部 Wiki など) への修正は
	// コミットが立たないので sha を書けない。URL を必須にすると、URL を持たない
	// 対象 (ローカルの外部ツール設定など) で同じ行き詰まりが起きるため、
	// 「URL か notes のどちらか」を必須にする。
	//
	// URL は sha ほど強い証拠にならない。sha はリポジトリがある限り不変だが、
	// PR 本文の URL は現在の本文を返すので、後から修正の前後を判別できないため。
	// applied_external_url は「反映先を指すもの」であって「反映内容を固定するもの」
	// ではない。だから notes には反映を確認した方法を書く。
	AppliedExternalURL string `yaml:"applied_external_url"`
	Notes              string `yaml:"notes"`
}

// recordDocDag は plans[].doc_dag (修正の後の doc-dag の確認の対象と結果)。
type recordDocDag struct {
	Scope  string `yaml:"scope"`
	Result string `yaml:"result"`
}

// recordVerification は plans[].verification を表し、観点 B で再確認した範囲 (near_edges) を持つ。
type recordVerification struct {
	NearEdges []string `yaml:"near_edges"`
}

// recordInvestigation は plans[].investigation (直す前の調査の範囲と結果)。
// scope は調べた範囲 (実行したコマンドと目で読んだ対象)、included は同じ原因の
// 別の現れとして問題に含めた箇所、excluded は見つけたが含めなかった箇所と理由。
// included / excluded が両方空なら「調べたが波及先は無かった」。
type recordInvestigation struct {
	Scope    string   `yaml:"scope"`
	Included []string `yaml:"included"`
	Excluded []string `yaml:"excluded"`
}

// recordAllowedKeys は階層ごとに許すキー。未知のキーは報告する。旧いキー名の
// 残存が「エラーなしで空」として扱われる種類の欠陥を避けるため。attrs だけは任意のキーを許す
// (上流固有の属性のパススルー)。
var recordAllowedKeys = map[string]map[string]bool{
	"トップレベル": {"runs": true},
	"実行": {"date": true, "skill": true, "run_id": true, "model": true, "level": true,
		"scope": true, "head": true, "findings": true, "plans": true, "recurrence": true, "notes": true},
	"指摘": {"id": true, "file": true, "line": true, "summary": true, "category": true,
		"audience": true, "audience_initial": true, "consequence": true, "premise_check": true,
		"gates_fired": true, "verdict": true, "verdict_reason": true, "plan_ref": true, "origin": true, "prior_defect": true, "attrs": true},
	"束ね先":     {"run": true, "problem": true},
	"前からある欠陥": {"base": true, "line_check": true, "line_reason": true, "same_defect": true, "same_defect_reason": true},
	"帰結":      {"condition": true, "who": true, "what": true, "detectability": true},
	"根拠の検証":   {"stages": true, "result": true},
	"修正計画": {"problem_id": true, "cause": true, "finding_ids": true, "approach": true,
		"investigation": true, "verification": true, "doc_dag": true, "options": true, "order": true, "depends_on": true, "sha": true,
		"status": true, "applied_external_url": true, "notes": true},
	"調査":          {"scope": true, "included": true, "excluded": true},
	"検証":          {"near_edges": true},
	"doc-dag の確認": {"scope": true, "result": true},
	"検知":          {"status": true, "evidence": true, "declined_reason": true, "reframe": true},
	"根拠":          {"condition": true, "finding_id": true, "prior_run": true, "prior": true, "reason": true},
	"捉え直し":        {"pattern": true, "axes": true, "root_cause": true, "fix_unit": true, "source": true},
}

// reviewTriageRecordProblems は記録のディレクトリの YAML を検査する。
// README.md は対象外。検査は (1) スキーマ (未知キー・必須キー・列挙値・参照の整合)、
// (2) サマリの鮮度 (YAML から生成した内容と *.md の一致)、(3) 孤児のサマリ。
func reviewTriageRecordProblems(files []string, readFile func(string) ([]byte, error)) []string {

content.content:
420	// 同一になり、書き込み元は書いたつもりのまま記録上は無い扱いになる (実測:
421	// investigation: だけの記録が検査 0 件でサマリにも出なかった)。
422	// 旧様式の recurrence も同じで、null は「無い」と同一になり、書きかけの項目が消える。
423	// consequence / premise_check の null は必須サブキーの欠落として既に報告されるので
424	// ここに含めない。重ねると 1 つの書き忘れが複数の問題になるため。
425	var recordNullSilentKeys = map[string]bool{"plan_ref": true, "prior_defect": true, "investigation": true, "verification": true, "doc_dag": true, "recurrence": true}
426	
427	// recordUnknownKeyProblems は許可キー集合との突き合わせで未知のキーと、
428	// 値の無い構造キー (recordNullSilentKeys) を列挙する。
429	// 問題が見つかっても走査を続け、他の問題の報告を妨げない。
430	func recordUnknownKeyProblems(f string, n *yaml.Node) []string {
431		var problems []string
432		var walkMap func(n *yaml.Node, kind string)
433		walkSeq := func(n *yaml.Node, kind string) {
434			if n == nil || n.Kind != yaml.SequenceNode {
435				return
436			}
437			for _, item := range n.Content {
438				walkMap(item, kind)
439			}
440		}
441		walkMap = func(n *yaml.Node, kind string) {
442			if n == nil || n.Kind != yaml.MappingNode {
443				return
444			}
445			allowed := recordAllowedKeys[kind]
446			for i := 0; i+1 < len(n.Content); i += 2 {
447				k, v := n.Content[i], n.Content[i+1]
448				if !allowed[k.Value] {
449					problems = append(problems, fmt.Sprintf(
450						"%s:%d: %sに未知のキー %q。旧いキー名の残存か、キーを書く位置のミス (上流固有の属性は attrs へ) を疑う",
451						f, k.Line, kind, k.Value))
452					continue
453				}
454				if recordNullSilentKeys[k.Value] && v.Kind == yaml.ScalarNode && v.Tag == "!!null" {
455					problems = append(problems, fmt.Sprintf(
456						"%s:%d: %s の %s に値がありません。書くなら中身を書き、書かないならキーごと消す (値の無いキーは「無い」と同じに扱われ、書いたつもりの記録が警告なく消える)",
457						f, k.Line, kind, k.Value))
458					continue
459				}
460				switch k.Value {
461				case "runs":
462					walkSeq(v, "実行")
463				case "findings":
464					walkSeq(v, "指摘")
465				case "plans":
466					walkSeq(v, "修正計画")
467				case "consequence":
468					walkMap(v, "帰結")
469				case "premise_check":
470					walkMap(v, "根拠の検証")
471				case "plan_ref":
472					walkMap(v, "束ね先")
473				case "prior_defect":
474					walkMap(v, "前からある欠陥")
475				case "investigation":
476					walkMap(v, "調査")
477				case "verification":
478					walkMap(v, "検証")
479				case "doc_dag":
480					walkMap(v, "doc-dag の確認")
481				case "recurrence":
482					walkMap(v, "検知")
483				case "evidence":
484					walkSeq(v, "根拠")
485				case "reframe":
486					walkMap(v, "捉え直し")
487				}
488			}
489		}
490		walkMap(n, "トップレベル")
491		return problems
492	}
493	
494	var recordDateRe = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}$`)
495	
496	// recordAudiences は被害者の列挙 (glossary のロール + 開発者)。設定 (.claude/review-triage.yaml)
497	// の audience と同じ値域。
498	var recordAudiences = map[string]bool{
499		"operator": true, "admin": true, "provider": true, "developer": true,
500	}
501	
502	// recordSemanticProblems は必須キー・列挙値・参照の整合を検査する。
503	func recordSemanticProblems(f string, doc *recordDoc) []string {
504		var problems []string
505		add := func(format string, args ...any) {
506			problems = append(problems, f+": "+fmt.Sprintf(format, args...))
507		}
508		if len(doc.Runs) == 0 {
509			add("runs がありません (実行が 1 つも無い)")
510		}
511		// 回ごとの問題 id の索引 (plan_ref の解決と被覆の検査に使う)。
512		plansByRun := make([]map[string]bool, len(doc.Runs))
513		for ri, run := range doc.Runs {
514			plansByRun[ri] = map[string]bool{}
515			for _, pl := range run.Plans {
516				plansByRun[ri][pl.ProblemID] = true
517			}
518		}
519		priorDefectFirstRun := recordPriorDefectFirstRun(doc.Runs)
520		for ri, run := range doc.Runs {
521			rn := fmt.Sprintf("runs[%d] (%s %s)", ri, run.Date, run.Skill)
522			if !recordDateRe.MatchString(run.Date) {
523				add("%s: date が YYYY-MM-DD ではありません: %q", rn, run.Date)
524			}
525			if run.Skill == "" {
526				add("%s: skill がありません", rn)
527			}
528			if run.Model == "" {
529				add("%s: model がありません (レビューを実行したモデルを必ず残す)", rn)
530			}
531			if run.Scope != "incremental" && run.Scope != "full" {
532				add("%s: scope は incremental / full のいずれか: %q", rn, run.Scope)
533			}
534			if run.Head == "" {
535				add("%s: head がありません (レビュー時点の短縮 SHA)", rn)
536			}
537	
538			priorDefectRequired := priorDefectFirstRun >= 0 && ri >= priorDefectFirstRun
539			verdictByID := map[int]string{}
540			for fi, fd := range run.Findings {
541				fn := fmt.Sprintf("%s: findings[%d] (id %d)", rn, fi, fd.ID)
542				if fd.ID <= 0 {
543					add("%s: id は正の整数にする", fn)
544				} else if _, dup := verdictByID[fd.ID]; dup {
545					add("%s: id が同じ回の中で重複しています", fn)
546				}
547				verdictByID[fd.ID] = fd.Verdict
548				for _, kv := range []struct{ key, val string }{
549					{"file", fd.File}, {"summary", fd.Summary},
550					{"category", fd.Category}, {"audience", fd.Audience},
551				} {
552					if kv.val == "" {
553						add("%s: %s がありません", fn, kv.key)
554					}
555				}
556				// audience の列挙。列挙外の値をエラーにせずに通すと D7 (被害者の判定) の入力が壊れる。
557				if fd.Audience != "" && !recordAudiences[fd.Audience] {
558					add("%s: audience は operator / admin / provider / developer のいずれか: %q", fn, fd.Audience)
