// 値の無い構造キー (recordNullSilentKeys) を列挙する。
// 問題が見つかっても走査を続け、他の問題の報告を妨げない。
func recordUnknownKeyProblems(f string, n *yaml.Node) []string {
	var problems []string
	var walkMap func(n *yaml.Node, kind string)
	walkSeq := func(n *yaml.Node, kind string) {
		if n == nil || n.Kind != yaml.SequenceNode {
			return
		}
		for _, item := range n.Content {
			walkMap(item, kind)
		}
	}
	walkMap = func(n *yaml.Node, kind string) {
		if n == nil || n.Kind != yaml.MappingNode {
			return
		}
		allowed := recordAllowedKeys[kind]
		for i := 0; i+1 < len(n.Content); i += 2 {
			k, v := n.Content[i], n.Content[i+1]
			if !allowed[k.Value] {
				problems = append(problems, fmt.Sprintf(
					"%s:%d: %sに未知のキー %q。旧いキー名の残存か、キーを書く位置のミス (上流固有の属性は attrs へ) を疑う",
					f, k.Line, kind, k.Value))
				continue
			}
			if recordNullSilentKeys[k.Value] && v.Kind == yaml.ScalarNode && v.Tag == "!!null" {
				problems = append(problems, fmt.Sprintf(
					"%s:%d: %s の %s に値がありません。書くなら中身を書き、書かないならキーごと消す (値の無いキーは「無い」と同じに扱われ、書いたつもりの記録が警告なく消える)",
					f, k.Line, kind, k.Value))
				continue
			}
			switch k.Value {
			case "runs":
				walkSeq(v, "実行")
			case "findings":
				walkSeq(v, "指摘")
			case "plans":
				walkSeq(v, "修正計画")
			case "consequence":
				walkMap(v, "帰結")
			case "premise_check":
				walkMap(v, "根拠の検証")
			case "plan_ref":
				walkMap(v, "束ね先")
			case "prior_defect":
				walkMap(v, "前からある欠陥")
			case "investigation":
				walkMap(v, "調査")
			case "verification":
				walkMap(v, "検証")
			case "doc_dag":
