1038	// renderFindingCells は指摘 1 件の表のセル列を返す。行を 1 つの書式文字列で
1039	// 組み立てると、テストがセル単位で分岐を検証できず、存在確認のアサーションが
1040	// 別のセルへの偶然一致で合格してしまう (実測で 3 度起きた種類の欠陥)。
1041	func renderFindingCells(fd recordFinding) []string {
1042		loc := fd.File
1043		if fd.Line > 0 {
1044			loc = fmt.Sprintf("%s:%d", fd.File, fd.Line)
1045		}
1046		aud := fd.Audience
1047		if fd.AudienceInitial != "" && fd.AudienceInitial != fd.Audience {
1048			aud = fd.AudienceInitial + " → " + fd.Audience
1049		}
1050		premise := "対象外"
1051		if fd.PremiseCheck.Stages != "none" {
1052			premise = fd.PremiseCheck.Stages + ": " + fd.PremiseCheck.Result
1053		}
1054		gates := "—"
1055		if len(fd.GatesFired) > 0 {
1056			gates = strings.Join(fd.GatesFired, ", ")
1057		}
1058		summary := recordCell(fd.Summary)
1059		if fd.Origin == "residual" {
1060			// 上流の residual をループ中に自己採択した指摘。上流の指摘と区別して読めるようにする。
1061			summary = "(residual の自己採択) " + summary
1062		}
1063		return []string{
1064			strconv.Itoa(fd.ID),
1065			"`" + recordCell(loc) + "` " + summary,
1066			recordCell(fd.Category) + " / " + recordCell(aud),
1067			recordCell(fd.Consequence.Condition) + " / " + recordCell(fd.Consequence.What) +
1068				" / " + recordCell(fd.Consequence.Detectability),
1069			premise,
1070			recordCell(gates),
1071			renderVerdictCell(fd),
1072		}
1073	}
1074	
1075	// renderVerdictCell は判定セル (判定 — 経路。D8 の結果と束ね先があれば添える) を返す。
