// recordDependsOnCycles は plans の depends_on の循環を検出する。自己参照は
// 個別に報告するのでここでは扱わない。同じ循環は 1 度だけ返す。
func recordDependsOnCycles(plans []recordPlan) [][]string {
	deps := make(map[string][]string, len(plans))
	for _, pl := range plans {
		for _, d := range pl.DependsOn {
			if d != pl.ProblemID {
				deps[pl.ProblemID] = append(deps[pl.ProblemID], d)
			}
		}
	}
	const (
		visiting = 1
		done     = 2
	)
	state := map[string]int{}
	var cycles [][]string
	var stack []string
	var visit func(id string)
	visit = func(id string) {
		state[id] = visiting
		stack = append(stack, id)
		for _, d := range deps[id] {
			switch state[d] {
			case 0:
				visit(d)
			case visiting:
				// stack の d 以降が循環。
				for i, s := range stack {
					if s == d {
						cycle := append(append([]string{}, stack[i:]...), d)
						cycles = append(cycles, cycle)
						break
					}
				}
			}
		}
		stack = stack[:len(stack)-1]
		state[id] = done
	}
	for _, pl := range plans {
		if state[pl.ProblemID] == 0 {
			visit(pl.ProblemID)
		}
	}
	return cycles
}

// --- サマリの生成 ---

// renderReviewTriageSummary は記録 YAML から人が読むサマリ (Markdown) を生成する。
// 件数はすべてここで計算し、人が書いた集計をどこからも読まない。
func renderReviewTriageSummary(yamlPath string, data []byte) (string, error) {
	var doc recordDoc
	if err := yaml.Unmarshal(data, &doc); err != nil {
		return "", fmt.Errorf("%s: YAML を読めません: %w", yamlPath, err)
	}
	return renderReviewTriageSummaryDoc(yamlPath, &doc), nil
}

func renderReviewTriageSummaryDoc(yamlPath string, doc *recordDoc) string {
	base := path.Base(yamlPath)
	stem := strings.TrimSuffix(base, ".yaml")
	var b strings.Builder
	fmt.Fprintf(&b, "<!-- 生成物。手で編集しない。SSOT は %s。`%s` で再生成する。 -->\n\n", base, summaryCommand)
	fmt.Fprintf(&b, "# %s のトリアージ記録\n\n", stem)
	fmt.Fprintf(&b, "SSOT は [%s](%s)。読み方と収束の目安は [README](README.md)。\n\n", base, base)

	b.WriteString("## 推移\n\n")
	b.WriteString("| 回 | 日付 | スキル | model | scope | 全件 | 採択 | 保留 | 却下 |\n")
	b.WriteString("| --- | --- | --- | --- | --- | --- | --- | --- | --- |\n")
	for i, run := range doc.Runs {
		adopted, held, rejected := 0, 0, 0
		for _, fd := range run.Findings {
			switch fd.Verdict {
			case "adopted":
				adopted++
			case "held":
				held++
			case "rejected":
				rejected++
			}
		}
		// 自由文字列の欄 (skill・model など) は recordCell で無害化する。縦棒が
		// 入ると桁がずれ、偽の数字が集計値の手前に並ぶため (列挙で守られない欄は検査も
		// 捕まえない)。
		fmt.Fprintf(&b, "| %d | %s | `%s` | `%s` | %s | %d | %d | %d | %d |\n",
			i+1, recordCell(run.Date), recordCell(run.Skill), recordCell(run.Model),
			recordCell(run.Scope), len(run.Findings), adopted, held, rejected)
	}

	for i, run := range doc.Runs {
		// 鮮度の検査は描画結果の全文一致なので、サマリに出す文言を変えると、ディレクトリに残る
		// 既存のサマリがすべて古いと報告される。0.24.0 で回の書き方を「N 回目」に変えたときは、
		// 再生成が要ることを README の「生成サマリの書式の変更」に書いた。束ね先・根拠の行・
		// 出所の文言も同じ。
		fmt.Fprintf(&b, "\n## %d 回目: %s `%s`", i+1, recordCell(run.Date), recordCell(run.Skill))
		if run.RunID != "" {
			fmt.Fprintf(&b, " (%s)", recordCell(run.RunID))
		}
		b.WriteString("\n\n")
		fmt.Fprintf(&b, "- HEAD `%s` / model `%s` / scope %s",
			recordCell(run.Head), recordCell(run.Model), recordCell(run.Scope))
		if run.Level != "" {
			b.WriteString(" / level " + recordCell(run.Level))
		}
		b.WriteString("\n\n")

		b.WriteString("| # | 指摘 | 分類 / 被害者 | 帰結 (条件 / 何が / 気づけるか) | 検証 | ゲート | 判定 |\n")
		b.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
		for _, fd := range run.Findings {
			b.WriteString(recordRow(renderFindingCells(fd)))
		}

		// 旧様式の検知の項目。既存の生成サマリを書き換えないよう、位置 (修正計画の前)
		// と文面を変えない。推移の表にも列を足さない。無い回には出さない (検知を
		// 廃止した後の回は常に無い)。
		if run.Recurrence != nil {
			b.WriteString("\n### 検知\n\n")
			renderRecurrence(&b, run.Recurrence)
		}

		if len(run.Plans) > 0 {
			b.WriteString("\n### 修正計画\n\n")
			// 最終列の見出しは「証拠」にする。最終列は、コミットの SHA だけでなくリポジトリ外の
			// 反映先の URL も取るため (renderPlanCells の証拠の欄)。見出しを SHA のままにすると、
			// done-external の行に出る URL を SHA として読ませることになる。
			b.WriteString("| 問題 | 原因 | 含む指摘 | 修正方法 | 順 | 状態 | 証拠 (SHA / URL) |\n")
			b.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
			for _, pl := range run.Plans {
				b.WriteString(recordRow(renderPlanCells(pl)))
			}
			// 調査済み・未立案 (investigated) の注記。調査フェーズの結果だけがあり、修正方法と
			// 順序をまだ持たない問題が残っている回にだけ、表の下に件数と問題 id を出す。
			// 無い回には 1 バイトも出さず、推移の表にも列を足さない。鮮度の検査が描画結果の
			// 全文一致なので、無い記録の出力が変わるとディレクトリの既存サマリがすべて古いと
			// 報告されるため (旧様式の検知の小節と同じ形)。
			renderInvestigatedNote(&b, run.Plans)
			for _, pl := range run.Plans {
				if pl.Status == "awaiting-human" {
					fmt.Fprintf(&b, "\n- **%s は選択待ち (人間が選ぶ)**: %s\n", recordCell(pl.ProblemID), recordCell(pl.Options))
				}
			}
			// リポジトリ外への反映は、コミットを辿っても内容を確認できない。
			// 反映を確認した方法 (notes) を表の外に出して、後から追えるようにする。
			for _, pl := range run.Plans {
				if pl.Status == "done-external" && pl.Notes != "" {
					fmt.Fprintf(&b, "\n- **%s はリポジトリ外へ反映済み**: %s\n", recordCell(pl.ProblemID), recordCell(pl.Notes))
				}
			}
			// 直す前の調査の範囲と結果。次のレビューで同じ種類の指摘が来たとき、前回の
			// 調査漏れ (範囲の外だった) か新規かを判別する材料なので表の外に出す。
			// 無い問題は出さない。無いことが「未調査」を表すため。
			for _, pl := range run.Plans {
				if pl.Investigation != nil {
					fmt.Fprintf(&b, "\n- **%s の調査**: %s\n", recordCell(pl.ProblemID), renderInvestigation(pl.Investigation))
				}
			}
		}

		if run.Notes != "" {
			b.WriteString("\n### 観察\n\n" + strings.TrimRight(run.Notes, "\n") + "\n")
		}
	}
	return b.String()
}

// recordRow はセルのスライスから表の 1 行を組み立てる。
func recordRow(cells []string) string {
	return "| " + strings.Join(cells, " | ") + " |\n"
}

// recordPriorDefectProblems は指摘 1 件の prior_defect (D8 の結果) を検査する。
// 書く条件は D8 に進んだかで決まる。判定フローでは、D4 で根拠を確認した指摘
// (premise_check.result が verified) だけが D8 に進む。required が偽の回
// (recordPriorDefectFirstRun の回より前の回) では、無くても報告しない。
func recordPriorDefectProblems(required bool, fd recordFinding) []string {
	var problems []string
	add := func(format string, args ...any) {
		problems = append(problems, fmt.Sprintf(format, args...))
	}
	verified := fd.PremiseCheck.Result == "verified"
	pd := fd.PriorDefect
	if pd == nil {
		if verified && required {
			add("prior_defect がありません (D4 で根拠を確認した指摘は D8 で判定するので、D8 の結果を書く。この記録では、この回かそれより前の回で prior_defect を書いている)")
		}
		return problems
	}
	if !verified {
		// D8 に進んでいない指摘の D8 の結果は、どの値でも判定の経路と矛盾するので、中身は検査しない。
		add("prior_defect は D8 で判定した指摘 (premise_check.result が verified) にだけ書く (result %q)", fd.PremiseCheck.Result)
		return problems
	}
	lineValid := true
	switch pd.LineCheck {
	case "holds", "not-holds", "unverifiable":
	default:
		lineValid = false
		add("prior_defect.line_check は holds / not-holds / unverifiable のいずれか: %q", pd.LineCheck)
	}
	if pd.LineReason == "" {
		add("prior_defect.line_reason がありません ((1) の結果の理由。道具 lineorigin の理由と行ごとの内訳)")
	}
	if (pd.LineCheck == "holds" || pd.LineCheck == "not-holds") && pd.Base == "" {
		add("prior_defect.base がありません (line_check が %s なら、道具に渡した全量の起点がある)", pd.LineCheck)
	}
	switch {
	case pd.LineCheck == "holds":
		switch pd.SameDefect {
		case "holds", "not-holds", "unverifiable":
		case "":
			add("prior_defect.same_defect がありません (line_check が holds なら (2) を確認する)")
		default:
			add("prior_defect.same_defect は holds / not-holds / unverifiable のいずれか: %q", pd.SameDefect)
		}
		if pd.SameDefect != "" && pd.SameDefectReason == "" {
			add("prior_defect.same_defect_reason がありません ((2) の根拠。全量の起点の内容の該当箇所)")
		}
	case lineValid:
		// (1) が成り立たないか確認できなければ D8 は当たらないと決まり、(2) は確認しない。
		// line_check が列挙外のときは、(2) を書くべきかが決まらないので報告しない。
		if pd.SameDefect != "" || pd.SameDefectReason != "" {
			add("prior_defect.same_defect と same_defect_reason は、line_check が holds のときだけ書く (line_check %q)", pd.LineCheck)
		}
	}
	if priorDefectHit(pd) && fd.Verdict != "held" {
		add("prior_defect では D8 が当たる ((1) holds、(2) %s) のに、verdict が held ではありません (D8 が当たれば H7 の保留): %q", pd.SameDefect, fd.Verdict)
	}
	return problems
}

// renderFindingCells は指摘 1 件の表のセル列を返す。行を 1 つの書式文字列で
// 組み立てると、テストがセル単位で分岐を検証できず、存在確認のアサーションが
// 別のセルへの偶然一致で合格してしまう (実測で 3 度起きた種類の欠陥)。
func renderFindingCells(fd recordFinding) []string {
	loc := fd.File
	if fd.Line > 0 {
		loc = fmt.Sprintf("%s:%d", fd.File, fd.Line)
	}
	aud := fd.Audience
	if fd.AudienceInitial != "" && fd.AudienceInitial != fd.Audience {
		aud = fd.AudienceInitial + " → " + fd.Audience
	}
	premise := "対象外"
	if fd.PremiseCheck.Stages != "none" {
		premise = fd.PremiseCheck.Stages + ": " + fd.PremiseCheck.Result
	}
	gates := "—"
	if len(fd.GatesFired) > 0 {
		gates = strings.Join(fd.GatesFired, ", ")
	}
	summary := recordCell(fd.Summary)
	if fd.Origin == "residual" {
		// 上流の residual をループ中に自己採択した指摘。上流の指摘と区別して読めるようにする。
		summary = "(residual の自己採択) " + summary
	}
	return []string{
		strconv.Itoa(fd.ID),
		"`" + recordCell(loc) + "` " + summary,
		recordCell(fd.Category) + " / " + recordCell(aud),
		recordCell(fd.Consequence.Condition) + " / " + recordCell(fd.Consequence.What) +
			" / " + recordCell(fd.Consequence.Detectability),
		premise,
		recordCell(gates),
		renderVerdictCell(fd),
	}
}

// renderVerdictCell は判定セル (判定 — 経路。D8 の結果と束ね先があれば添える) を返す。
// D8 の結果は prior_defect を書いた指摘にだけ添える。過去の記録の生成サマリを変えないため。
func renderVerdictCell(fd recordFinding) string {
	cell := recordVerdictJa(fd.Verdict) + " — " + recordCell(fd.VerdictReason)
	if pd := fd.PriorDefect; pd != nil {
		hit := "当たらない"
		if priorDefectHit(pd) {
			hit = "当たる"
		}
		cell += " (D8: " + hit + "。(1) " + recordCell(pd.LineCheck)
		if pd.SameDefect != "" {
			cell += "、(2) " + recordCell(pd.SameDefect)
		}
		cell += ")"
	}
	if fd.PlanRef != nil {
		// 文言はサマリに出る (変えたときの扱いは renderReviewTriageSummaryDoc の回の見出しのコメント)
		cell += fmt.Sprintf(" (束ね先: %d 回目の %s)", fd.PlanRef.Run, recordCell(fd.PlanRef.Problem))
	}
	return cell
}

