973	// recordRow はセルのスライスから表の 1 行を組み立てる。
974	func recordRow(cells []string) string {
975		return "| " + strings.Join(cells, " | ") + " |\n"
976	}
977	
978	// recordPriorDefectProblems は指摘 1 件の prior_defect (D8 の結果) を検査する。
979	// 書く条件は D8 に進んだかで決まる。判定フローでは、D4 で根拠を確認した指摘
980	// (premise_check.result が verified) だけが D8 に進む。required が偽の回
981	// (recordPriorDefectFirstRun の回より前の回) では、無くても報告しない。
982	func recordPriorDefectProblems(required bool, fd recordFinding) []string {
983		var problems []string
984		add := func(format string, args ...any) {
985			problems = append(problems, fmt.Sprintf(format, args...))
986		}
987		verified := fd.PremiseCheck.Result == "verified"
988		pd := fd.PriorDefect
989		if pd == nil {
990			if verified && required {
991				add("prior_defect がありません (D4 で根拠を確認した指摘は D8 で判定するので、D8 の結果を書く。この記録では、この回かそれより前の回で prior_defect を書いている)")
992			}
993			return problems
994		}
995		if !verified {
996			// D8 に進んでいない指摘の D8 の結果は、どの値でも判定の経路と矛盾するので、中身は検査しない。
997			add("prior_defect は D8 で判定した指摘 (premise_check.result が verified) にだけ書く (result %q)", fd.PremiseCheck.Result)
998			return problems
999		}
1000		lineValid := true
1001		switch pd.LineCheck {
1002		case "holds", "not-holds", "unverifiable":
1003		default:
1004			lineValid = false
1005			add("prior_defect.line_check は holds / not-holds / unverifiable のいずれか: %q", pd.LineCheck)
1006		}
1007		if pd.LineReason == "" {
1008			add("prior_defect.line_reason がありません ((1) の結果の理由。道具 lineorigin の理由と行ごとの内訳)")
1009		}
1010		if (pd.LineCheck == "holds" || pd.LineCheck == "not-holds") && pd.Base == "" {
1011			add("prior_defect.base がありません (line_check が %s なら、道具に渡した全量の起点がある)", pd.LineCheck)
1012		}
1013		switch {
1014		case pd.LineCheck == "holds":
1015			switch pd.SameDefect {
1016			case "holds", "not-holds", "unverifiable":
1017			case "":
1018				add("prior_defect.same_defect がありません (line_check が holds なら (2) を確認する)")
1019			default:
1020				add("prior_defect.same_defect は holds / not-holds / unverifiable のいずれか: %q", pd.SameDefect)
1021			}
1022			if pd.SameDefect != "" && pd.SameDefectReason == "" {
1023				add("prior_defect.same_defect_reason がありません ((2) の根拠。全量の起点の内容の該当箇所)")
1024			}
1025		case lineValid:
1026			// (1) が成り立たないか確認できなければ D8 は当たらないと決まり、(2) は確認しない。
1027			// line_check が列挙外のときは、(2) を書くべきかが決まらないので報告しない。
1028			if pd.SameDefect != "" || pd.SameDefectReason != "" {
1029				add("prior_defect.same_defect と same_defect_reason は、line_check が holds のときだけ書く (line_check %q)", pd.LineCheck)
1030			}
1031		}
1032		if priorDefectHit(pd) && fd.Verdict != "held" {
1033			add("prior_defect では D8 が当たる ((1) holds、(2) %s) のに、verdict が held ではありません (D8 が当たれば H7 の保留): %q", pd.SameDefect, fd.Verdict)
1034		}
1035		return problems
1036	}
